// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 1000000000000000000); }

    function testFuzz_property(address actor, uint256 extra) public {
        // only EOA-like actors can reach wager (onlyRealPeople => tx.origin)
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        uint256 bet = c.currentBetLimit();

        c.OpenToThePublic();

        // first wager must always succeed for any actor with the exact bet limit
        vm.deal(actor, bet * 2);
        vm.prank(actor, actor);
        c.wager{value: bet}();
        bool firstOk = c.hasPlayerWagered(actor);

        // second wager from the SAME actor to the same bet limit:
        // reference reverts, mutant accepts
        vm.prank(actor, actor);
        (bool secondOk, ) = address(c).call{value: bet}(abi.encodeWithSignature("wager()"));

        // The reference must never allow a second wager while
        // wagers[msg.sender] > 0; therefore a successful duplicate wager
        // must be impossible.  Equivalently, after a duplicate attempt,
        // hasPlayerWagered must still describe the single original wager.
        assertTrue(firstOk && !secondOk);
    }
}
